WITH unpacked AS (SELECT id, customer_id, created_at, coupon_codes, items, attributes, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, SIZE(attributes) AS num_attributes, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, i) -> acc + i.qty * i.price, acc -> ROUND(acc, 2)) AS cart_value, COALESCE(ship_to.city, 'UNKNOWN') AS city_or_unknown, COALESCE(attributes['device'], 'unknown') AS device_or_default FROM carts WHERE TO_DATE(created_at) < '2023-10-10') SELECT id, customer_id, created_at, coupon_codes, items, attributes, coupons_text, num_attributes, cart_value, city_or_unknown, device_or_default, SUM(num_attributes) OVER (ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) num_attributes_sum_30m, NTILE(4) OVER (PARTITION BY customer_id ORDER BY num_attributes DESC, id) num_attributes_bucket, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY num_attributes, id) seq_no, LEAD(cart_value, 2) OVER (PARTITION BY customer_id ORDER BY created_at, id) next_cart_value FROM unpacked
